import React, { useEffect } from 'react';
import '../css/LoginPage.css';

const LoginPage = () => {

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const handleDemoLogin = (type) => {
    alert(`${type} 로그인은 포트폴리오 데모 기능입니다.`);
  };

  return (
    <main className="login-page">

      <div className="login-box">

        <div className="login-content">

          {/* 로고 느낌 */}
          <div className="login-ticket-icon">
            🎟
          </div>

          <h1 className="login-title">
            타임티켓에
            <br />
            오신 것을 환영해요!
          </h1>


          {/* 로그인 버튼 */}
          <div className="login-buttons">

            <button
              className="login-social naver"
              onClick={() => handleDemoLogin('네이버')}
            >
              <strong className="naver-icon">N</strong>

              <span>
                네이버로 시작하기
              </span>
            </button>


            <button
              className="login-social kakao"
              onClick={() => handleDemoLogin('카카오')}
            >
              <span className="kakao-icon">●</span>

              <span>
                카카오로 시작하기
              </span>
            </button>


            <button
              className="login-timeticket"
              onClick={() =>
                handleDemoLogin('타임티켓 아이디')
              }
            >
              타임티켓 아이디로 시작하기
            </button>

          </div>


          {/* 아래 메뉴 */}
          <div className="login-bottom">

            <div className="login-bottom-row">

              <span>
                외국인이신가요?
              </span>

              <button
                onClick={() =>
                  alert('외국인 가입 데모 화면입니다.')
                }
              >
                외국인가입
              </button>

            </div>


            <div className="login-bottom-row">

              <span>
                계정을 잃어버리셨나요?
              </span>

              <button
                onClick={() =>
                  alert('계정찾기 데모 기능입니다.')
                }
              >
                계정찾기
              </button>

            </div>

          </div>

        </div>

      </div>

    </main>
  );
};

export default LoginPage;