import React from "react";
import { useNavigate } from "react-router-dom";

import "../css/SectionCardList.css";

const SectionCardList = ({ title, data }) => {
  const navigate = useNavigate();

  return (
    <section className="section-card-list">
      {/* 섹션 헤더 */}
      <div className="section-card-header">
        <h3 className="section-card-title">
          {title}
        </h3>

        <span
          className="section-card-more"
          onClick={() => navigate("/tickets")}
        >
          전체보기 &gt;
        </span>
      </div>

      {/* 5단 티켓 카드 그리드 */}
      <div className="section-card-grid">
        {data.map((ticket) => (
          <div
            key={ticket.id}
            className="section-ticket-card hover-card"
            onClick={() =>
              navigate(`/detail/${ticket.id}`)
            }
          >
            {/* 포스터 */}
            <div className="section-ticket-image-box">
              <img
                src={
                  process.env.PUBLIC_URL +
                  ticket.img
                }
                alt={ticket.title}
              />
            </div>

            {/* 장소 */}
            <div className="section-ticket-place">
              {ticket.place}
            </div>

            {/* 제목 */}
            <div className="section-ticket-title">
              {ticket.title}
            </div>

            {/* 가격 */}
            <div className="section-ticket-price">
              {ticket.discountRate && (
                <span className="section-ticket-discount">
                  {ticket.discountRate}%
                </span>
              )}

              <span>
                {ticket.salePrice.toLocaleString()}원
              </span>
            </div>

            {/* 태그 */}
            {ticket.tag && (
              <div className="section-ticket-tag-wrap">
                <span className="section-ticket-tag">
                  {ticket.tag}
                </span>
              </div>
            )}
          </div>
        ))}
      </div>
    </section>
  );
};

export default SectionCardList;