import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';

import ticketData from '../db/ticketData';
import '../css/TrendPage.css';

function TrendPage() {

  // 페이지 진입 시 맨 위로 이동
  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  // 선택한 성별
  const [gender, setGender] = useState('');

  // 선택한 연령대
  const [age, setAge] = useState('');

  // 결과를 보여줄지 여부
  const [showResult, setShowResult] = useState(false);


  // 성별
  const genders = [
    '여성',
    '남성'
  ];


  // 연령대
  const ages = [
    '10대',
    '20대',
    '30대',
    '40대',
    '50+'
  ];


  // 또래의 픽 확인하기
  const handleSearch = () => {

    if (!gender || !age) {
      alert('성별과 연령대를 선택해주세요.');
      return;
    }

    setShowResult(true);
  };


// =========================
// 또래픽 필터
// =========================

// 선택한 성별의 비율 가져오기
const getGenderValue = (item) => {

  if (!item.genderStats) return 0;

  if (gender === '여성') {
    return item.genderStats.female || 0;
  }

  if (gender === '남성') {
    return item.genderStats.male || 0;
  }

  return 0;
};


// 선택한 연령대의 비율 가져오기
const getAgeValue = (item) => {

  if (!item.ageStats) return 0;

  const ageKey = {
    '10대': 'teen',
    '20대': 'twenties',
    '30대': 'thirties',
    '40대': 'forties',
    '50+': 'fiftyPlus'
  };

  return item.ageStats[ageKey[age]] || 0;
};


// 성별 + 연령대 점수를 계산해서 높은 순으로 정렬
const trendTickets = showResult
  ? ticketData
      .filter(
        (item) =>
          item.genderStats &&
          item.ageStats
      )
      .map((item) => {

        const genderScore = getGenderValue(item);
        const ageScore = getAgeValue(item);

        return {
          ...item,

          // 또래픽 순위 계산용 점수
          trendScore: genderScore + ageScore,

          // 화면에 표시할 비율
          selectedGenderRate: genderScore,
          selectedAgeRate: ageScore
        };

      })
      .sort(
        (a, b) =>
          b.trendScore - a.trendScore
      )
      .slice(0, 5)
  : [];


  return (

    <div className="trend-page">


      {/* 페이지 제목 */}

      <div className="trend-title">

        <div>

          <h1>또래픽</h1>

          <p>
            나랑 비슷한 사람들은 어떤 티켓을 예매할까?
          </p>

        </div>

        <span>
          최근 30일 실제 예매 · 매일 자정 갱신
        </span>

      </div>


      {/* 왼쪽 + 오른쪽 */}

      <div className="trend-container">


        {/* 왼쪽 선택 영역 */}

        <div className="trend-filter">


          {/* 성별 */}

          <div className="filter-row">

            <strong>
              성별
            </strong>

            <div className="gender-buttons">

              {genders.map((item) => (

                <button
                  key={item}
                  className={
                    gender === item
                      ? 'active'
                      : ''
                  }
                  onClick={() => setGender(item)}
                >
                  {item}
                </button>

              ))}

            </div>

          </div>


          {/* 연령대 */}

          <div className="filter-row">

            <strong>
              연령대
            </strong>

            <div className="age-buttons">

              {ages.map((item) => (

                <button
                  key={item}
                  className={
                    age === item
                      ? 'active'
                      : ''
                  }
                  onClick={() => setAge(item)}
                >
                  {item}
                </button>

              ))}

            </div>

          </div>


          {/* 확인 버튼 */}

          <button
            className="trend-search-button"
            onClick={handleSearch}
          >
            또래의 픽 확인하기
          </button>


          {/* 안내 문구 */}

          <div className="trend-notice">

            <p>
              · 실제 예매자들의 성별·연령 통계를 기준으로 순위를 보여줘요.
            </p>

            <p>
              · 최근 30일 예매 기준이며, 매일 자정에 갱신돼요.
            </p>

            <p>
              · 개인을 알 수 없는 익명 통계로만 다뤄요.
            </p>

          </div>

        </div>


        {/* 오른쪽 결과 영역 */}

        <div className="trend-result">

          {!showResult ? (

            <div className="trend-empty">

              <div className="trend-icon">
                ♧
              </div>

              <h2>
                내 또래의 선택은?
              </h2>

            </div>

          ) : trendTickets.length === 0 ? (

            <div className="trend-empty">

              <h2>
                조건에 맞는 티켓이 없습니다.
              </h2>

              <p>
                다른 성별 또는 연령대를 선택해보세요.
              </p>

            </div>

          ) : (

            <div className="trend-result-content">

              <h2>
                {age} {gender}이 많이 선택한 티켓
              </h2>
<div className="trend-ticket-list">

  {trendTickets.map((item, index) => (

    <Link
      key={item.id}
      to={`/detail/${item.id}`}
      className="trend-ticket"
    >

      {/* =========================
          순위
      ========================= */}

      <div className="trend-rank">
        {index + 1}
      </div>


      {/* =========================
          티켓 이미지
      ========================= */}

      <img
        className="trend-ticket-image"
        src={item.img}
        alt={item.title}
      />


      {/* =========================
          티켓 기본 정보
      ========================= */}

      <div className="trend-ticket-info">

        <span className="trend-genre">
          {item.genre}
        </span>

        <h3>
          {item.title}
        </h3>

        <p>
          📍 {item.place}
        </p>

        <strong>
          {item.salePrice.toLocaleString()}원
        </strong>

      </div>


      {/* =========================
          성별 통계
      ========================= */}

      <div className="trend-stat">

        <div className="stat-title">
          성별
        </div>

        <div className="gender-stat-label">

          <span>
            여성 {item.genderStats.female}%
          </span>

          <span>
            남성 {item.genderStats.male}%
          </span>

        </div>


        <div className="gender-stat-bar">

          <div
            className="female-bar"
            style={{
              width: `${item.genderStats.female}%`
            }}
          />

          <div
            className="male-bar"
            style={{
              width: `${item.genderStats.male}%`
            }}
          />

        </div>

      </div>


      {/* =========================
          연령 통계
      ========================= */}

      <div className="trend-stat age-stat">

        <div className="stat-title">
          연령
        </div>

        <div className="age-bars">

          {[
            ['10대', item.ageStats.teen],
            ['20대', item.ageStats.twenties],
            ['30대', item.ageStats.thirties],
            ['40대', item.ageStats.forties],
            ['50+', item.ageStats.fiftyPlus]
          ].map(([label, value]) => (

            <div
              className="age-bar-item"
              key={label}
            >

              <span className="age-percent">
                {value}%
              </span>

              <div className="age-bar-background">

                <div
                  className="age-bar-fill"
                  style={{
                    height: `${Math.max(value * 1.5, 8)}px`
                  }}
                />

              </div>

              <span className="age-label">
                {label}
              </span>

            </div>

          ))}

        </div>

      </div>

    </Link>

  ))}

</div>

            </div>

          )}

        </div>

      </div>

    </div>
  );
}

export default TrendPage;