import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

import ticketData from '../db/ticketData';
import '../css/BudgetTickets.css';

const BudgetTickets = () => {
  const navigate = useNavigate();

  const [activeTab, setActiveTab] = useState('under_10k');

  const tabList = [
    { id: 'under_10k', label: '~1만원' },
    { id: '10k_30k', label: '1만원~3만원' },
    { id: 'over_30k', label: '3만원~' },
    { id: 'all', label: '전체보기' }
  ];

  const tickets = ticketData || [];

  // 선택한 가격대에 맞는 티켓만 필터링
  const filteredTickets = tickets.filter((ticket) => {
    if (activeTab === 'under_10k') {
      return ticket.salePrice <= 10000;
    }

    if (activeTab === '10k_30k') {
      return (
        ticket.salePrice > 10000 &&
        ticket.salePrice <= 30000
      );
    }

    if (activeTab === 'over_30k') {
      return ticket.salePrice > 30000;
    }

    return true;
  });

  return (
    <section className="budget-section">

      <h3 className="budget-title">
        예산에 맞는 티켓을 알아보세요
      </h3>

      {/* 가격 탭 */}
      <div className="budget-tabs">
        {tabList.map((tab) => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={
              activeTab === tab.id
                ? 'budget-tab active'
                : 'budget-tab'
            }
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* 티켓 목록 */}
      <div className="budget-grid">
        {filteredTickets
          .slice(0, 9)
          .map((ticket) => (

            <div
              key={ticket.id}
              className="budget-card hover-card"
              onClick={() =>
                navigate(`/detail/${ticket.id}`)
              }
            >
              {/* 이미지 */}
              <div className="budget-image-box">
                <img
                  src={
                    process.env.PUBLIC_URL +
                    ticket.img
                  }
                  alt={ticket.title}
                  onError={(e) => {
                    e.target.style.display = 'none';
                  }}
                />
              </div>

              {/* 정보 */}
              <div className="budget-info">

                <div className="budget-place">
                  {ticket.place} · {ticket.genre}
                </div>

                <div className="budget-ticket-title">
                  {ticket.title}
                </div>

                <div className="budget-price">
                  {ticket.discountRate && (
                    <span className="budget-discount">
                      {ticket.discountRate}%
                    </span>
                  )}

                  {ticket.salePrice.toLocaleString()}원
                </div>

              </div>
            </div>

          ))}
      </div>

    </section>
  );
};

export default BudgetTickets;