import React from "react";
import { Routes, Route } from "react-router-dom";
import "./App.css";

// 공통 레이아웃
import Header from "./components/Header";
import Footer from "./components/Footer";

// 메인 섹션 컴포넌트들
import HeroBanner from "./components/HeroBanner";
import ShortcutNav from "./components/ShortcutNav";
import LastCall from "./components/LastCall";
import NewOpen from "./components/NewOpen";
import BudgetTickets from "./components/BudgetTickets";
import SectionCardList from "./components/SectionCardList";

// 상세 페이지
import DetailPage from "./pages/DetailPage";
import CalendarPage from "./pages/CalendarPage";
import NearbyPage from "./pages/NearbyPage";
import TrendPage from "./pages/TrendPage";
import AllTicket from "./pages/AllTicket";
import LoginPage from "./pages/LoginPage";
import InquiryPage from "./pages/InquiryPage";

// 통합 데이터
import ticketData from "./db/ticketData";

// 메인 홈 컴포넌트
const Home = () => {
  // 카테고리별로 상품을 나눠서 사용
  const lastCallData = ticketData.filter(
    (item) => item.category === "lastCall",
  );

  const playData = ticketData.filter((item) => item.category === "play");
  const exhibitData = ticketData.filter((item) => item.category === "exhibit");
  const tourData = ticketData.filter((item) => item.category === "tour");
  const childrenData = ticketData.filter(
    (item) => item.category === "children",
  );

  return (
    <>
      <HeroBanner /> {/* 1. 5장 롤링 배너*/}
      <ShortcutNav /> {/* 2. 3대 탐색 바로가기*/}
      <LastCall /> {/* 3. 오늘 마감 임박*/}
      <NewOpen /> {/* 4. 오픈 예정 도미노 롤링 */} 
      <BudgetTickets /> {/* 5. 예산대별 티켓 탭*/}

      {/* 6. 공통 4단 티켓 그리드 */}
      <SectionCardList title="놓치면 다시 보기 어려운 공연" data={playData} />
      <SectionCardList title="부담없이 다녀오기 좋은 전시" data={exhibitData} />
      <SectionCardList title="해설사와 함께하는 문화체험" data={tourData} />
      <SectionCardList title="아이들이 좋아하는 공연·전시" data={childrenData}/>
    </>
  );
};

function App() {
  return (
    <div className="App">
      {/* 헤더는 모든 페이지 상단에 공통 유지 */}
      <Header />

      {/* 페이지 라우팅 */}
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/detail/:id" element={<DetailPage />} />
        <Route path="/calendar" element={<CalendarPage />} />
        <Route path="/nearby" element={<NearbyPage />} />
        <Route path="/trend" element={<TrendPage />} />
        <Route path="/tickets" element={<AllTicket />} />
        <Route path="/login" element={<LoginPage />} />
        <Route path="/inquiry" element={<InquiryPage />} />
      </Routes>

      {/* 푸터는 모든 페이지 하단에 공통 유지 */}
      <Footer />
    </div>
  );
}

export default App;
