import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

import ticketData from "../db/ticketData";
import "../css/NewOpen.css";

const NewOpen = () => {
  const navigate = useNavigate();

  // ticketData에서 공연 데이터만 가져오기
  const allTickets = ticketData.filter(
    (ticket) => ticket.category === "play"
  );

  // 오늘 날짜
  const today = new Date();

  const getDynamicDate = (offsetDays) => {
    const target = new Date(today);

    target.setDate(
      target.getDate() + offsetDays
    );

    const m = target.getMonth() + 1;
    const d = target.getDate();

    return `${m}.${d}`;
  };

  // 3개 칸이 현재 보여주는 데이터 인덱스
  const [slotIndices, setSlotIndices] = useState([
    0,
    1,
    2
  ]);

  // 각 칸의 롤링 애니메이션 상태
  const [animating, setAnimating] = useState([
    false,
    false,
    false
  ]);

  useEffect(() => {
    const interval = setInterval(() => {

      // 첫 번째 슬롯
      setAnimating((prev) => [
        true,
        prev[1],
        prev[2]
      ]);

      // 두 번째 슬롯
      setTimeout(() => {
        setAnimating((prev) => [
          prev[0],
          true,
          prev[2]
        ]);
      }, 250);

      // 세 번째 슬롯
      setTimeout(() => {
        setAnimating((prev) => [
          prev[0],
          prev[1],
          true
        ]);
      }, 500);

      // 다음 상품으로 변경
      setTimeout(() => {
        setSlotIndices((prev) => [
          (prev[0] + 3) % allTickets.length,
          (prev[1] + 3) % allTickets.length,
          (prev[2] + 3) % allTickets.length
        ]);

        setAnimating([
          false,
          false,
          false
        ]);
      }, 1100);

    }, 4500);

    return () => clearInterval(interval);

  }, [allTickets.length]);

  return (
    <section className="newopen-section">

      {/* 제목 */}
      <div className="newopen-header">

        <h3 className="newopen-title">
          새롭게 오픈한 티켓
        </h3>

        <span
          className="newopen-more"
          onClick={() => navigate("/tickets")}
        >
          전체보기 &gt;
        </span>

      </div>

      {/* 외곽 박스 */}
      <div className="newopen-box">

        <div className="newopen-row">

          {[0, 1, 2].map((slotIndex) => {

            const currentItem =
              allTickets[
                slotIndices[slotIndex]
              ];

            const nextIndex =
              (
                slotIndices[slotIndex] + 3
              ) % allTickets.length;

            const nextItem =
              allTickets[nextIndex];

            const isSlotAnimating =
              animating[slotIndex];

            return (
              <React.Fragment key={slotIndex}>

                {/* 슬롯 */}
                <div className="newopen-slot">

                  <div
                    className={
                      isSlotAnimating
                        ? "newopen-slide active"
                        : "newopen-slide"
                    }
                  >

                    {/* 현재 상품 */}
                    <div
                      className="newopen-item"
                      onClick={() =>
                        navigate(
                          `/detail/${currentItem.id}`
                        )
                      }
                    >
                      <img
                        className="newopen-image"
                        src={
                          process.env.PUBLIC_URL +
                          currentItem.img
                        }
                        alt={
                          currentItem.title
                        }
                      />

                      <span className="newopen-item-title">
                        {currentItem.title}
                      </span>

                      <span className="newopen-badge today">

                        <span className="blinking-dot" />

                        오늘 오픈

                      </span>

                    </div>

                    {/* 다음 상품 */}
                    <div
                      className="newopen-item"
                      onClick={() =>
                        navigate(
                          `/detail/${nextItem.id}`
                        )
                      }
                    >
                      <img
                        className="newopen-image"
                        src={
                          process.env.PUBLIC_URL +
                          nextItem.img
                        }
                        alt={
                          nextItem.title
                        }
                      />

                      <span className="newopen-item-title">
                        {nextItem.title}
                      </span>

                      <span className="newopen-badge next">

                        <span className="static-dot" />

                        {getDynamicDate(1)} 오픈

                      </span>

                    </div>

                  </div>

                </div>

                {/* 슬롯 구분선 */}
                {slotIndex < 2 && (
                  <div className="newopen-divider" />
                )}

              </React.Fragment>
            );
          })}

        </div>

      </div>

    </section>
  );
};

export default NewOpen;