import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';

import ticketData from '../db/ticketData';
import '../css/NearbyPage.css';

function NearbyPage() {

  const [selectedRegion, setSelectedRegion] = useState('');
    useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const regions = [
    '대학로',
    '서울',
    '경기',
    '충청',
    '경상',
    '전라',
    '강원',
    '제주'
  ];

  const filteredTickets = selectedRegion
    ? ticketData.filter((item) =>
        item.place.includes(selectedRegion)
      )
    : [];

  return (
    <div className="nearby-page">

      {/* 제목 */}
      <div className="nearby-title">

        <h1>내 주위 티켓</h1>

        <p>
          내 주위의 예매 가능한 티켓을 지도에서 찾아보세요
        </p>

      </div>


      {/* 지도 + 티켓 */}
      <div className="nearby-container">


        {/* 왼쪽 */}
        <div className="nearby-map">

          <div className="nearby-map-content">

            {!selectedRegion ? (

              <div className="nearby-region">

                <h2>
                  지역을 선택해주세요
                </h2>

                <p>
                  위치 사용을 허용하면<br />
                  더 정확하게 내 주위 티켓을 보여드려요.
                </p>

                <div className="region-buttons">

                  {regions.map((region) => (

                    <button
                      key={region}
                      className={
                        selectedRegion === region
                          ? 'active'
                          : ''
                      }
                      onClick={() => setSelectedRegion(region)}
                    >
                      {region}
                    </button>

                  ))}

                </div>

              </div>

            ) : (

              <div className="nearby-selected-region">

                <h2>
                  {selectedRegion}
                </h2>

                <p>
                  선택한 지역의 티켓을 확인해보세요.
                </p>

                <button
                  onClick={() => setSelectedRegion('')}
                >
                  지역 다시 선택
                </button>

              </div>

            )}

          </div>

        </div>


        {/* 오른쪽 */}
        <div className="nearby-ticket-list">

          <div className="nearby-ticket-header">

            <h2>
              📍 내 주위 티켓
            </h2>

          </div>


          <div className="nearby-tickets">

            {!selectedRegion ? (

              <div className="nearby-empty">
                지도에서 지역을 선택해주세요.
              </div>

            ) : filteredTickets.length === 0 ? (

              <div className="nearby-empty">
                해당 지역에 등록된 티켓이 없습니다.
              </div>

            ) : (

              filteredTickets.map((item) => (

                <Link
                  key={item.id}
                  to={`/detail/${item.id}`}
                  className="nearby-ticket"
                >

                  <img
                    src={item.img}
                    alt={item.title}
                  />

                  <div className="nearby-ticket-info">

                    <span className="genre">
                      {item.genre}
                    </span>

                    <h3>
                      {item.title}
                    </h3>

                    <p>
                      📍 {item.place}
                    </p>

                    <strong>
                      {item.salePrice.toLocaleString()}원
                    </strong>

                  </div>

                </Link>

              ))

            )}

          </div>

        </div>

      </div>

    </div>
  );
}

export default NearbyPage;