import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

import ticketData from "../db/ticketData";
import "../css/LastCall.css";

const LastCall = () => {
  const navigate = useNavigate();

  // ticketData에서 라스트 콜 상품만 가져오기
  const lastCallData = ticketData.filter(
    (ticket) => ticket.category === "lastCall"
  );

  // 1초마다 줄어드는 카운트다운 타이머
  const [seconds, setSeconds] = useState(43 * 60 + 19);

  useEffect(() => {
    const timer = setInterval(() => {
      setSeconds((prev) => (prev > 0 ? prev - 1 : 0));
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  // 초 단위를 00:00:00 형식으로 변환
  const formatTime = (totalSeconds) => {
    const h = String(
      Math.floor(totalSeconds / 3600)
    ).padStart(2, "0");

    const m = String(
      Math.floor((totalSeconds % 3600) / 60)
    ).padStart(2, "0");

    const s = String(
      totalSeconds % 60
    ).padStart(2, "0");

    return `${h}:${m}:${s}`;
  };

  return (
    <section className="lastcall-section">

      {/* 제목 */}
      <div className="lastcall-header">

        <h3 className="lastcall-title">
          라스트 콜
        </h3>

        <span
          className="lastcall-more"
          onClick={() => navigate("/tickets")}
        >
          전체보기 &gt;
        </span>

      </div>

      {/* 티켓 목록 */}
      <div className="lastcall-grid">

        {lastCallData.map((ticket) => (

          <div
            key={ticket.id}
            className="lastcall-card hover-card"
            onClick={() =>
              navigate(`/detail/${ticket.id}`)
            }
          >

            {/* 포스터 이미지 */}
            <div className="lastcall-image-box">
              <img
                src={
                  process.env.PUBLIC_URL +
                  ticket.img
                }
                alt={ticket.title}
              />
            </div>

            {/* 관람 시간 */}
            <div className="lastcall-time">
              오늘 {ticket.time} 관람
            </div>

            {/* 제목 */}
            <div className="lastcall-ticket-title">
              {ticket.title}
            </div>

            {/* 가격 */}
            <div className="lastcall-price">

              {ticket.discountRate !== null && (
                <span className="lastcall-discount">
                  {ticket.discountRate}%
                </span>
              )}

              {ticket.salePrice.toLocaleString()}원

            </div>

            {/* 잔여석 / 마감시간 */}
            <div className="lastcall-bottom">

              <span className="lastcall-seat">
                2매 남음
              </span>

              <span className="lastcall-deadline">
                ⏰ 마감 {formatTime(seconds)} 전
              </span>

            </div>

          </div>

        ))}

      </div>

    </section>
  );
};

export default LastCall;