import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import "../css/Header.css";

function Header() {
  const navigate = useNavigate();

  const [searchText, setSearchText] = useState("");

  // 달력 버튼 클릭
  const goToCalendar = () => {
    navigate("/calendar");
  };

  // 검색 실행
  const handleSearch = () => {
    const keyword = searchText.trim();

    if (!keyword) {
      navigate("/tickets");
      return;
    }

    navigate(`/tickets?search=${encodeURIComponent(keyword)}`);
  };

  // Enter 키 검색
  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      handleSearch();
    }
  };

  return (
    <header className="header">
      {/* 맨 위 프로모션 배너 */}
      <div className="top-banner">
        <img src="/img/banner01.jpg" alt="2026 공연 관람료 할인" />
      </div>

      {/* 상단 */}
      <div className="header-top">
        {/* 로고 */}
        <Link to="/" className="logo">
          time ticket
        </Link>

        {/* 검색창 */}
        <div className="search-box">
          <input
            type="text"
            placeholder="검색어를 입력하세요"
            value={searchText}
            onChange={(e) => setSearchText(e.target.value)}
            onKeyDown={handleKeyDown}
          />

          <span onClick={handleSearch} style={{ cursor: "pointer" }}>
            🔍
          </span>
        </div>
        {/* 오른쪽 메뉴 */}
        <div className="header-right">
          {/* 고객센터 */}
          <div className="header-menu customer-menu">
            <div className="header-menu-button">
              <img
                src="/img/icon2.svg"
                alt="고객센터"
                className="header-menu-icon"
              />
              <span>고객센터</span>
            </div>

            {/* 고객센터 드롭다운 */}
            <div className="customer-dropdown">
              <span>공지사항</span>
              <span>자주 묻는 질문</span>

              <span onClick={() => navigate("/inquiry")}>1:1 문의</span>
            </div>
          </div>

          {/* 로그인·가입 */}
          <div className="header-menu" onClick={() => navigate("/login")}>
            <div className="header-menu-button">
              <img
                src="/img/icon1.svg"
                alt="로그인·가입"
                className="header-menu-icon"
              />
              <span>로그인·가입</span>
            </div>
          </div>
        </div>
      </div>

      {/* 하단 메뉴 */}
      <div className="header-bottom">
        <nav className="main-menu">
          {/* 달력 버튼 */}
          <button className="calendar-button" onClick={goToCalendar}>
            <span className="calendar-icon">📅</span>
          </button>

          <Link to="/tickets">연극</Link>
          <Link to="/tickets">뮤지컬</Link>
          <Link to="/tickets">콘서트</Link>
          <Link to="/tickets">전시</Link>
          <Link to="/tickets">문화체험</Link>
        </nav>

        <nav className="sub-menu">
          <span>⏰ 타임세일</span>
          <span>🏆 실시간 랭킹</span>
          <span>📈 급상승</span>
          <span>🎁 무료초대</span>
        </nav>
      </div>
    </header>
  );
}

export default Header;
