import React, { useEffect, useState } from 'react';
import '../css/InquiryPage.css';

const InquiryPage = () => {

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const [form, setForm] = useState({
    type: '예매/결제',
    title: '',
    email: '',
    content: ''
  });

  const handleChange = (e) => {

    const { name, value } = e.target;

    setForm((prev) => ({
      ...prev,
      [name]: value
    }));
  };


  const handleSubmit = (e) => {

    e.preventDefault();

    if (
      !form.title.trim() ||
      !form.email.trim() ||
      !form.content.trim()
    ) {
      alert('문의 내용을 모두 입력해주세요.');
      return;
    }

    alert('문의가 등록되었습니다.');

    setForm({
      type: '예매/결제',
      title: '',
      email: '',
      content: ''
    });
  };


  return (
    <main className="inquiry-page">

      <div className="inquiry-container">

        <div className="inquiry-header">

          <h1>
            1:1 문의
          </h1>

          <p>
            궁금한 내용을 남겨주시면 확인 후 답변드리겠습니다.
          </p>

        </div>


        <form
          className="inquiry-form"
          onSubmit={handleSubmit}
        >

          {/* 문의 유형 */}
          <div className="inquiry-field">

            <label>
              문의 유형
            </label>

            <select
              name="type"
              value={form.type}
              onChange={handleChange}
            >
              <option>예매/결제</option>
              <option>취소/환불</option>
              <option>티켓 이용</option>
              <option>회원정보</option>
              <option>기타문의</option>
            </select>

          </div>


          {/* 제목 */}
          <div className="inquiry-field">

            <label>
              제목
            </label>

            <input
              type="text"
              name="title"
              value={form.title}
              onChange={handleChange}
              placeholder="문의 제목을 입력해주세요."
            />

          </div>


          {/* 이메일 */}
          <div className="inquiry-field">

            <label>
              이메일
            </label>

            <input
              type="email"
              name="email"
              value={form.email}
              onChange={handleChange}
              placeholder="답변 받을 이메일을 입력해주세요."
            />

          </div>


          {/* 문의 내용 */}
          <div className="inquiry-field">

            <label>
              문의 내용
            </label>

            <textarea
              name="content"
              value={form.content}
              onChange={handleChange}
              placeholder="문의 내용을 자세히 입력해주세요."
            />

          </div>


          <div className="inquiry-notice">
            ※ 본 페이지는 포트폴리오용 데모 문의 기능입니다.
          </div>


          <button
            type="submit"
            className="inquiry-submit"
          >
            문의하기
          </button>

        </form>

      </div>

    </main>
  );
};

export default InquiryPage;