import React, { useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";

import ticketData from "../db/ticketData";
import "../css/AllTicket.css";

const AllTicket = () => {
  const navigate = useNavigate();

  // 주소창의 ?search=검색어 가져오기
  const [searchParams] = useSearchParams();

  const searchKeyword = searchParams.get("search") || "";

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [searchKeyword]);

  // 검색 기능
  const filteredTickets = ticketData.filter((ticket) => {
    const keyword = searchKeyword.toLowerCase().trim();

    // 검색어가 없으면 전체 25개
    if (!keyword) {
      return true;
    }

    const title = ticket.title?.toLowerCase() || "";

    const place = ticket.place?.toLowerCase() || "";

    const genre = ticket.genre?.toLowerCase() || "";

    return (
      title.includes(keyword) ||
      place.includes(keyword) ||
      genre.includes(keyword)
    );
  });

  return (
    <main className="allticket-page">
      {/* 제목 */}
      <div className="allticket-header">
        <h1 className="allticket-title">
          {searchKeyword ? `"${searchKeyword}" 검색 결과` : "전체 티켓"}
        </h1>

        <p className="allticket-description">
          {searchKeyword
            ? `총 ${filteredTickets.length}개의 티켓을 찾았습니다.`
            : "공연 · 전시 · 문화체험 티켓을 한눈에 확인해보세요."}
        </p>
      </div>

      {/* 검색 결과가 없는 경우 */}
      {filteredTickets.length === 0 ? (
        <div className="allticket-empty">검색 결과가 없습니다.</div>
      ) : (
        /* 티켓 목록 */
        <div className="allticket-grid">
          {filteredTickets.map((ticket) => (
            <div
              key={ticket.id}
              className="allticket-card hover-card"
              onClick={() => navigate(`/detail/${ticket.id}`)}
            >
              {/* 포스터 */}
              <div className="allticket-image-box">
                <img
                  src={process.env.PUBLIC_URL + ticket.img}
                  alt={ticket.title}
                />
              </div>

              {/* 장소 */}
              <div className="allticket-place">{ticket.place}</div>

              {/* 제목 */}
              <div className="allticket-ticket-title">{ticket.title}</div>

              {/* 가격 */}
              <div className="allticket-price">
                {ticket.discountRate && (
                  <span className="allticket-discount">
                    {ticket.discountRate}%
                  </span>
                )}

                <span>{ticket.salePrice.toLocaleString()}원</span>
              </div>
            </div>
          ))}
        </div>
      )}
    </main>
  );
};

export default AllTicket;
